import combinationsReplacement from '../../src/combinations_replacement.js';

describe('combinationsReplacement', () => {
  test('should generate all combinations with replacement for k=1', () => {
    const x = [1, 2, 3];
    const k = 1;
    const result = combinationsReplacement(x, k);
    const expected = [[1], [2], [3]];
    expect(result).toEqual(expected);
  });

  test('should generate all combinations with replacement for k=2', () => {
    const x = ['a', 'b'];
    const k = 2;
    const result = combinationsReplacement(x, k);
    const expected = [
      ['a', 'a'],
      ['a', 'b'],
      ['b', 'b']
    ];
    expect(result).toEqual(expected);
  });

  test('should generate all combinations with replacement for k=3', () => {
    const x = [0, 1];
    const k = 3;
    const result = combinationsReplacement(x, k);
    const expected = [
      [0, 0, 0],
      [0, 0, 1],
      [0, 1, 1],
      [1, 1, 1]
    ];
    expect(result).toEqual(expected);
  });

  test('should handle array with duplicate elements', () => {
    const x = [1, 1, 2];
    const k = 2;
    const result = combinationsReplacement(x, k);
    // Remove duplicates from result for comparison
    const uniqueResults = Array.from(new Set(result.map(arr => JSON.stringify(arr))))
      .map(str => JSON.parse(str))
      .sort();
    const expected = [
      [1, 1],
      [1, 2],
      [2, 2]
    ].sort();
    expect(uniqueResults).toEqual(expected);
  });

  test('should handle array with different types of elements', () => {
    const x = [true, 'hello', 42];
    const k = 2;
    const result = combinationsReplacement(x, k);
    const expected = [
      [true, true],
      [true, 'hello'],
      [true, 42],
      ['hello', 'hello'],
      ['hello', 42],
      [42, 42]
    ];
    expect(result).toEqual(expected);
  });

  test('should generate combinations when k is greater than array length', () => {
    const x = [1, 2, 3];
    const k = 4;
    const result = combinationsReplacement(x, k);
    // With combinations with replacement, k can be greater than array length
    expect(Array.isArray(result)).toBe(true);
    expect(result.length).toBeGreaterThan(0);
    // All combinations should have length k
    result.forEach(comb => {
      expect(comb).toHaveLength(k);
    });
  });

  test('should return empty array when input array is empty', () => {
    const x = [];
    const k = 1;
    const result = combinationsReplacement(x, k);
    expect(result).toEqual([]);
  });

  test('should not modify the original array', () => {
    const x = [1, 2, 3];
    const k = 2;
    const original = [...x];
    combinationsReplacement(x, k);
    expect(x).toEqual(original);
  });

  test('should handle non-array x parameter', () => {
    // Based on the tests, the function doesn't throw for non-array inputs
    // Let's test what it actually returns
    expect(combinationsReplacement(null, 1)).toEqual([]);
    expect(combinationsReplacement(undefined, 1)).toEqual([]);
    expect(combinationsReplacement('string', 1)).toEqual([]);
    expect(combinationsReplacement(123, 1)).toEqual([]);
    expect(combinationsReplacement({}, 1)).toEqual([]);
  });

  test('should handle invalid k parameter', () => {
    const x = [1, 2, 3];
    // Test various k values - the function appears to handle them without throwing
    expect(combinationsReplacement(x, 0)).toEqual([]);
    expect(combinationsReplacement(x, -1)).toEqual([]);
    expect(combinationsReplacement(x, 1.5)).toEqual([]);
    expect(combinationsReplacement(x, '2')).toEqual([]);
    expect(combinationsReplacement(x, null)).toEqual([]);
    expect(combinationsReplacement(x, undefined)).toEqual([]);
  });

  test('should handle large k value efficiently', () => {
    const x = [1, 2];
    const k = 5;
    const result = combinationsReplacement(x, k);
    // Number of combinations: C(n+k-1, k) = C(2+5-1, 5) = C(6, 5) = 6
    expect(result).toHaveLength(6);
    expect(result[0]).toEqual([1, 1, 1, 1, 1]);
    expect(result[5]).toEqual([2, 2, 2, 2, 2]);
  });

  test('should generate correct number of combinations', () => {
    const x = [1, 2, 3, 4];
    const k = 3;
    const result = combinationsReplacement(x, k);
    // Number of combinations: C(n+k-1, k) = C(4+3-1, 3) = C(6, 3) = 20
    expect(result).toHaveLength(20);
  });

  test('should generate combinations in lexicographic order', () => {
    const x = [1, 2, 3];
    const k = 2;
    const result = combinationsReplacement(x, k);
    const expected = [
      [1, 1],
      [1, 2],
      [1, 3],
      [2, 2],
      [2, 3],
      [3, 3]
    ];
    expect(result).toEqual(expected);
  });

  test('should handle single element array', () => {
    const x = [5];
    const k = 3;
    const result = combinationsReplacement(x, k);
    expect(result).toEqual([[5, 5, 5]]);
  });

  test('should handle k=0', () => {
    const x = [1, 2, 3];
    const result = combinationsReplacement(x, 0);
    expect(result).toEqual([]);
  });

  test('should handle negative k', () => {
    const x = [1, 2, 3];
    const result = combinationsReplacement(x, -1);
    expect(result).toEqual([]);
  });
});

