    expect(result[1]).toBeCloseTo(1 * Math.pow(e, -1), 10); // P(X=1) = 1 * e^-1
    expect(result[2]).toBeCloseTo(0.5 * Math.pow(e, -1), 10); // P(X=2) = 0.5 * e^-1
