    test('should handle different distribution types', () => {
      const uniformDistributionType = () => ({
        pdf: () => 0.2, // Constant probability
        range: [0, 5]
      });

      const exponentialDistributionType = () => ({
        pdf: (x) => Math.exp(-x),
        range: [0, 10]
      });

      const uniformResult = chiSquaredGoodnessOfFit(mockData, uniformDistributionType, validSignificance);
      const exponentialResult = chiSquaredGoodnessOfFit(mockData, exponentialDistributionType, validSignificance);

      expect(typeof uniformResult).toBe('boolean');
      expect(typeof exponentialResult).toBe('boolean');
    });

    test('should handle data with repeated values', () => {
      const repeatedData = [1.0, 1.0, 2.0, 2.0, 2.0, 3.0];
      const result = chiSquaredGoodnessOfFit(repeatedData, mockDistributionType, validSignificance);

      expect(typeof result).toBe('boolean');
    });

    test('should return consistent results for same inputs', () => {
      const result1 = chiSquaredGoodnessOfFit(mockData, mockDistributionType, validSignificance);
      const result2 = chiSquaredGoodnessOfFit(mockData, mockDistributionType, validSignificance);

      expect(result1).toBe(result2);
    });
  });

  describe('Boundary conditions', () => {
